50	/** Split mutation commands into two parts:
51	*   First part should be executed by mutations interpreter.
52	*   Other is just simple drop/renames, so they can be executed without interpreter.
53	*/
54	static void splitMutationCommands(
55	    MergeTreeData::DataPartPtr part,
56	    const MutationCommands & commands,
57	    MutationCommands & for_interpreter,
58	    MutationCommands & for_file_renames)
59	{
60	    ColumnsDescription part_columns(part->getColumns());
61	
62	    if (!isWidePart(part))
63	    {
64	        NameSet mutated_columns;
65	        for (const auto & command : commands)
66	        {
67	            if (command.type == MutationCommand::Type::MATERIALIZE_INDEX
68	                || command.type == MutationCommand::Type::MATERIALIZE_COLUMN
69	                || command.type == MutationCommand::Type::MATERIALIZE_PROJECTION
70	                || command.type == MutationCommand::Type::MATERIALIZE_TTL
71	                || command.type == MutationCommand::Type::DELETE
72	                || command.type == MutationCommand::Type::UPDATE)
73	            {
74	                for_interpreter.push_back(command);
75	                for (const auto & [column_name, expr] : command.column_to_update_expression)
76	                    mutated_columns.emplace(column_name);
77	
78	                if (command.type == MutationCommand::Type::MATERIALIZE_COLUMN)
79	                    mutated_columns.emplace(command.column_name);
80	            }
81	            else if (command.type == MutationCommand::Type::DROP_INDEX || command.type == MutationCommand::Type::DROP_PROJECTION)
82	            {
83	                for_file_renames.push_back(command);
84	            }
85	            else if (bool has_column = part_columns.has(command.column_name), has_nested_column = part_columns.hasNested(command.column_name); has_column || has_nested_column)
86	            {
87	                if (command.type == MutationCommand::Type::DROP_COLUMN || command.type == MutationCommand::Type::RENAME_COLUMN)
88	                {
89	                    if (has_nested_column)
90	                    {
91	                        const auto & nested = part_columns.getNested(command.column_name);
92	                        assert(!nested.empty());
93	                        for (const auto & nested_column : nested)
94	                            mutated_columns.emplace(nested_column.name);
95	                    }
96	                    else
97	                        mutated_columns.emplace(command.column_name);
98	                }
99	
100	                if (command.type == MutationCommand::Type::RENAME_COLUMN)
101	                {
102	                    for_interpreter.push_back(
103	                    {
104	                        .type = MutationCommand::Type::READ_COLUMN,
105	                        .column_name = command.rename_to,
106	                    });
107	                    part_columns.rename(command.column_name, command.rename_to);
108	                }
109	            }
110	        }
111	        /// If it's compact part, then we don't need to actually remove files
112	        /// from disk we just don't read dropped columns
113	        for (const auto & column : part->getColumns())
114	        {
115	            if (!mutated_columns.contains(column.name))
116	                for_interpreter.emplace_back(
117	                    MutationCommand{.type = MutationCommand::Type::READ_COLUMN, .column_name = column.name, .data_type = column.type});
118	        }
119	    }
120	    else
121	    {
122	        for (const auto & command : commands)
123	        {
124	            if (command.type == MutationCommand::Type::MATERIALIZE_INDEX
125	                || command.type == MutationCommand::Type::MATERIALIZE_COLUMN
126	                || command.type == MutationCommand::Type::MATERIALIZE_PROJECTION
127	                || command.type == MutationCommand::Type::MATERIALIZE_TTL
128	                || command.type == MutationCommand::Type::DELETE
129	                || command.type == MutationCommand::Type::UPDATE)
130	            {
131	                for_interpreter.push_back(command);
132	            }
133	            else if (command.type == MutationCommand::Type::DROP_INDEX || command.type == MutationCommand::Type::DROP_PROJECTION)
134	            {
135	                for_file_renames.push_back(command);
136	            }
137	            /// If we don't have this column in source part, than we don't need
138	            /// to materialize it
139	            else if (part_columns.has(command.column_name))
140	            {
141	                if (command.type == MutationCommand::Type::READ_COLUMN)
142	                {
143	                    for_interpreter.push_back(command);
144	                }
145	                else if (command.type == MutationCommand::Type::RENAME_COLUMN)
146	                {
147	                    part_columns.rename(command.column_name, command.rename_to);
148	                    for_file_renames.push_back(command);
149	                }
150	                else
151	                {
152	                    for_file_renames.push_back(command);
153	                }
154	            }
155	        }
156	    }
157	}
