159	/// Get the columns list of the resulting part in the same order as storage_columns.
160	static std::pair<NamesAndTypesList, SerializationInfoByName>
161	getColumnsForNewDataPart(
162	    MergeTreeData::DataPartPtr source_part,
163	    const Block & updated_header,
164	    NamesAndTypesList storage_columns,
165	    const SerializationInfoByName & serialization_infos,
166	    const MutationCommands & commands_for_removes)
167	{
168	    NameSet removed_columns;
169	    NameToNameMap renamed_columns_to_from;
170	    NameToNameMap renamed_columns_from_to;
171	    ColumnsDescription part_columns(source_part->getColumns());
172	
173	    /// All commands are validated in AlterCommand so we don't care about order
174	    for (const auto & command : commands_for_removes)
175	    {
176	        /// If we don't have this column in source part, than we don't need to materialize it
177	        if (!part_columns.has(command.column_name))
178	            continue;
179	
180	        if (command.type == MutationCommand::DROP_COLUMN)
181	            removed_columns.insert(command.column_name);
182	
183	        if (command.type == MutationCommand::RENAME_COLUMN)
184	        {
185	            renamed_columns_to_from.emplace(command.rename_to, command.column_name);
186	            renamed_columns_from_to.emplace(command.column_name, command.rename_to);
187	        }
188	    }
189	
190	    SerializationInfoByName new_serialization_infos;
191	    for (const auto & [name, info] : serialization_infos)
192	    {
193	        if (removed_columns.contains(name))
194	            continue;
195	
196	        auto it = renamed_columns_from_to.find(name);
197	        if (it != renamed_columns_from_to.end())
198	            new_serialization_infos.emplace(it->second, info);
199	        else
200	            new_serialization_infos.emplace(name, info);
201	    }
202	
203	    /// In compact parts we read all columns, because they all stored in a
204	    /// single file
205	    if (!isWidePart(source_part))
206	        return {updated_header.getNamesAndTypesList(), new_serialization_infos};
207	
208	    Names source_column_names = source_part->getColumns().getNames();
209	    NameSet source_columns_name_set(source_column_names.begin(), source_column_names.end());
210	    for (auto it = storage_columns.begin(); it != storage_columns.end();)
211	    {
212	        if (updated_header.has(it->name))
213	        {
214	            auto updated_type = updated_header.getByName(it->name).type;
215	            if (updated_type != it->type)
216	                it->type = updated_type;
217	            ++it;
218	        }
219	        else
220	        {
221	            if (!source_columns_name_set.contains(it->name))
222	            {
223	                /// Source part doesn't have column but some other column
224	                /// was renamed to it's name.
225	                auto renamed_it = renamed_columns_to_from.find(it->name);
226	                if (renamed_it != renamed_columns_to_from.end()
227	                    && source_columns_name_set.contains(renamed_it->second))
228	                    ++it;
229	                else
230	                    it = storage_columns.erase(it);
231	            }
232	            else
233	            {
234	                /// Check that this column was renamed to some other name
235	                bool was_renamed = renamed_columns_from_to.contains(it->name);
236	                bool was_removed = removed_columns.contains(it->name);
237	
238	                /// If we want to rename this column to some other name, than it
239	                /// should it's previous version should be dropped or removed
240	                if (renamed_columns_to_from.contains(it->name) && !was_renamed && !was_removed)
241	                    throw Exception(
242	                        ErrorCodes::LOGICAL_ERROR,
243	                        "Incorrect mutation commands, trying to rename column {} to {}, but part {} already has column {}", renamed_columns_to_from[it->name], it->name, source_part->name, it->name);
244	
245	                /// Column was renamed and no other column renamed to it's name
246	                /// or column is dropped.
247	                if (!renamed_columns_to_from.contains(it->name) && (was_renamed || was_removed))
248	                    it = storage_columns.erase(it);
249	                else
250	                    ++it;
251	            }
252	        }
253	    }
254	
255	    return {storage_columns, new_serialization_infos};
256	}
