259	static ExecuteTTLType shouldExecuteTTL(const StorageMetadataPtr & metadata_snapshot, const ColumnDependencies & dependencies)
260	{
261	    if (!metadata_snapshot->hasAnyTTL())
262	        return ExecuteTTLType::NONE;
263	
264	    bool has_ttl_expression = false;
265	
266	    for (const auto & dependency : dependencies)
267	    {
268	        if (dependency.kind == ColumnDependency::TTL_EXPRESSION)
269	            has_ttl_expression = true;
270	
271	        if (dependency.kind == ColumnDependency::TTL_TARGET)
272	            return ExecuteTTLType::NORMAL;
273	    }
274	    return has_ttl_expression ? ExecuteTTLType::RECALCULATE : ExecuteTTLType::NONE;
275	}
