278	/// Get skip indices, that should exists in the resulting data part.
279	static MergeTreeIndices getIndicesForNewDataPart(
280	    const IndicesDescription & all_indices,
281	    const MutationCommands & commands_for_removes)
282	{
283	    NameSet removed_indices;
284	    for (const auto & command : commands_for_removes)
285	        if (command.type == MutationCommand::DROP_INDEX)
286	            removed_indices.insert(command.column_name);
287	
288	    MergeTreeIndices new_indices;
289	    for (const auto & index : all_indices)
290	        if (!removed_indices.contains(index.name))
291	            new_indices.push_back(MergeTreeIndexFactory::instance().get(index));
292	
293	    return new_indices;
294	}
