314	/// Return set of indices which should be recalculated during mutation also
315	/// wraps input stream into additional expression stream
316	static std::set<MergeTreeIndexPtr> getIndicesToRecalculate(
317	    QueryPipelineBuilder & builder,
318	    const NameSet & updated_columns,
319	    const StorageMetadataPtr & metadata_snapshot,
320	    ContextPtr context,
321	    const NameSet & materialized_indices,
322	    const MergeTreeData::DataPartPtr & source_part)
323	{
324	    /// Checks if columns used in skipping indexes modified.
325	    const auto & index_factory = MergeTreeIndexFactory::instance();
326	    std::set<MergeTreeIndexPtr> indices_to_recalc;
327	    ASTPtr indices_recalc_expr_list = std::make_shared<ASTExpressionList>();
328	    const auto & indices = metadata_snapshot->getSecondaryIndices();
329	
330	    for (size_t i = 0; i < indices.size(); ++i)
331	    {
332	        const auto & index = indices[i];
333	
334	        bool has_index =
335	            source_part->checksums.has(INDEX_FILE_PREFIX + index.name + ".idx") ||
336	            source_part->checksums.has(INDEX_FILE_PREFIX + index.name + ".idx2");
337	        // If we ask to materialize and it already exists
338	        if (!has_index && materialized_indices.contains(index.name))
339	        {
340	            if (indices_to_recalc.insert(index_factory.get(index)).second)
341	            {
342	                ASTPtr expr_list = index.expression_list_ast->clone();
343	                for (const auto & expr : expr_list->children)
344	                    indices_recalc_expr_list->children.push_back(expr->clone());
345	            }
346	        }
347	        // If some dependent columns gets mutated
348	        else
349	        {
350	            bool mutate = false;
351	            const auto & index_cols = index.expression->getRequiredColumns();
352	            for (const auto & col : index_cols)
353	            {
354	                if (updated_columns.contains(col))
355	                {
356	                    mutate = true;
357	                    break;
358	                }
359	            }
360	            if (mutate && indices_to_recalc.insert(index_factory.get(index)).second)
361	            {
362	                ASTPtr expr_list = index.expression_list_ast->clone();
363	                for (const auto & expr : expr_list->children)
364	                    indices_recalc_expr_list->children.push_back(expr->clone());
365	            }
366	        }
367	    }
368	
369	    if (!indices_to_recalc.empty() && builder.initialized())
370	    {
371	        auto indices_recalc_syntax = TreeRewriter(context).analyze(indices_recalc_expr_list, builder.getHeader().getNamesAndTypesList());
372	        auto indices_recalc_expr = ExpressionAnalyzer(
373	                indices_recalc_expr_list,
374	                indices_recalc_syntax, context).getActions(false);
375	
376	        /// We can update only one column, but some skip idx expression may depend on several
377	        /// columns (c1 + c2 * c3). It works because this stream was created with help of
378	        /// MutationsInterpreter which knows about skip indices and stream 'in' already has
379	        /// all required columns.
380	        /// TODO move this logic to single place.
381	        builder.addTransform(std::make_shared<ExpressionTransform>(builder.getHeader(), indices_recalc_expr));
382	        builder.addTransform(std::make_shared<MaterializingTransform>(builder.getHeader()));
383	    }
384	    return indices_to_recalc;
385	}
