387	std::set<ProjectionDescriptionRawPtr> getProjectionsToRecalculate(
388	    const NameSet & updated_columns,
389	    const StorageMetadataPtr & metadata_snapshot,
390	    const NameSet & materialized_projections,
391	    const MergeTreeData::DataPartPtr & source_part)
392	{
393	    /// Checks if columns used in projections modified.
394	    std::set<ProjectionDescriptionRawPtr> projections_to_recalc;
395	    for (const auto & projection : metadata_snapshot->getProjections())
396	    {
397	        // If we ask to materialize and it doesn't exist
398	        if (!source_part->checksums.has(projection.name + ".proj") && materialized_projections.contains(projection.name))
399	        {
400	            projections_to_recalc.insert(&projection);
401	        }
402	        else
403	        {
404	            // If some dependent columns gets mutated
405	            bool mutate = false;
406	            const auto & projection_cols = projection.required_columns;
407	            for (const auto & col : projection_cols)
408	            {
409	                if (updated_columns.contains(col))
410	                {
411	                    mutate = true;
412	                    break;
413	                }
414	            }
415	            if (mutate)
416	                projections_to_recalc.insert(&projection);
417	        }
418	    }
419	    return projections_to_recalc;
420	}
