423	/// Files, that we don't need to remove and don't need to hardlink, for example columns.txt and checksums.txt.
424	/// Because we will generate new versions of them after we perform mutation.
425	NameSet collectFilesToSkip(
426	    const MergeTreeDataPartPtr & source_part,
427	    const Block & updated_header,
428	    const std::set<MergeTreeIndexPtr> & indices_to_recalc,
429	    const String & mrk_extension,
430	    const std::set<ProjectionDescriptionRawPtr> & projections_to_recalc)
431	{
432	    NameSet files_to_skip = source_part->getFileNamesWithoutChecksums();
433	
434	    /// Skip updated files
435	    for (const auto & entry : updated_header)
436	    {
437	        ISerialization::StreamCallback callback = [&](const ISerialization::SubstreamPath & substream_path)
438	        {
439	            String stream_name = ISerialization::getFileNameForStream({entry.name, entry.type}, substream_path);
440	            files_to_skip.insert(stream_name + ".bin");
441	            files_to_skip.insert(stream_name + mrk_extension);
442	        };
443	
444	        source_part->getSerialization({entry.name, entry.type})->enumerateStreams(callback);
445	    }
446	    for (const auto & index : indices_to_recalc)
447	    {
448	        files_to_skip.insert(index->getFileName() + ".idx");
449	        files_to_skip.insert(index->getFileName() + mrk_extension);
450	    }
451	    for (const auto & projection : projections_to_recalc)
452	        files_to_skip.insert(projection->getDirectoryName());
453	
454	    return files_to_skip;
455	}
