458	/// Apply commands to source_part i.e. remove and rename some columns in
459	/// source_part and return set of files, that have to be removed or renamed
460	/// from filesystem and in-memory checksums. Ordered result is important,
461	/// because we can apply renames that affects each other: x -> z, y -> x.
462	static NameToNameVector collectFilesForRenames(
463	    MergeTreeData::DataPartPtr source_part, const MutationCommands & commands_for_removes, const String & mrk_extension)
464	{
465	    /// Collect counts for shared streams of different columns. As an example, Nested columns have shared stream with array sizes.
466	    std::map<String, size_t> stream_counts;
467	    for (const auto & column : source_part->getColumns())
468	    {
469	        source_part->getSerialization(column)->enumerateStreams(
470	            [&](const ISerialization::SubstreamPath & substream_path)
471	            {
472	                ++stream_counts[ISerialization::getFileNameForStream(column, substream_path)];
473	            });
474	    }
475	
476	    NameToNameVector rename_vector;
477	    /// Remove old data
478	    for (const auto & command : commands_for_removes)
479	    {
480	        if (command.type == MutationCommand::Type::DROP_INDEX)
481	        {
482	            if (source_part->checksums.has(INDEX_FILE_PREFIX + command.column_name + ".idx2"))
483	            {
484	                rename_vector.emplace_back(INDEX_FILE_PREFIX + command.column_name + ".idx2", "");
485	                rename_vector.emplace_back(INDEX_FILE_PREFIX + command.column_name + mrk_extension, "");
486	            }
487	            else if (source_part->checksums.has(INDEX_FILE_PREFIX + command.column_name + ".idx"))
488	            {
489	                rename_vector.emplace_back(INDEX_FILE_PREFIX + command.column_name + ".idx", "");
490	                rename_vector.emplace_back(INDEX_FILE_PREFIX + command.column_name + mrk_extension, "");
491	            }
492	        }
493	        else if (command.type == MutationCommand::Type::DROP_PROJECTION)
494	        {
495	            if (source_part->checksums.has(command.column_name + ".proj"))
496	                rename_vector.emplace_back(command.column_name + ".proj", "");
497	        }
498	        else if (command.type == MutationCommand::Type::DROP_COLUMN)
499	        {
500	            ISerialization::StreamCallback callback = [&](const ISerialization::SubstreamPath & substream_path)
501	            {
502	                String stream_name = ISerialization::getFileNameForStream({command.column_name, command.data_type}, substream_path);
503	                /// Delete files if they are no longer shared with another column.
504	                if (--stream_counts[stream_name] == 0)
505	                {
506	                    rename_vector.emplace_back(stream_name + ".bin", "");
507	                    rename_vector.emplace_back(stream_name + mrk_extension, "");
508	                }
509	            };
510	
511	            auto column = source_part->getColumns().tryGetByName(command.column_name);
512	            if (column)
513	                source_part->getSerialization(*column)->enumerateStreams(callback);
514	        }
515	        else if (command.type == MutationCommand::Type::RENAME_COLUMN)
516	        {
517	            String escaped_name_from = escapeForFileName(command.column_name);
518	            String escaped_name_to = escapeForFileName(command.rename_to);
519	
520	            ISerialization::StreamCallback callback = [&](const ISerialization::SubstreamPath & substream_path)
521	            {
522	                String stream_from = ISerialization::getFileNameForStream({command.column_name, command.data_type}, substream_path);
523	
524	                String stream_to = boost::replace_first_copy(stream_from, escaped_name_from, escaped_name_to);
525	
526	                if (stream_from != stream_to)
527	                {
528	                    rename_vector.emplace_back(stream_from + ".bin", stream_to + ".bin");
529	                    rename_vector.emplace_back(stream_from + mrk_extension, stream_to + mrk_extension);
530	                }
531	            };
532	
533	            auto column = source_part->getColumns().tryGetByName(command.column_name);
534	            if (column)
535	                source_part->getSerialization(*column)->enumerateStreams(callback);
536	        }
537	    }
538	
539	    return rename_vector;
540	}
