543	/// Initialize and write to disk new part fields like checksums, columns, etc.
544	void finalizeMutatedPart(
545	    const MergeTreeDataPartPtr & source_part,
546	    const DataPartStorageBuilderPtr & data_part_storage_builder,
547	    MergeTreeData::MutableDataPartPtr new_data_part,
548	    ExecuteTTLType execute_ttl_type,
549	    const CompressionCodecPtr & codec,
550	    ContextPtr context)
551	{
552	    //auto disk = new_data_part->volume->getDisk();
553	    //auto part_path = fs::path(new_data_part->getRelativePath());
554	
555	    if (new_data_part->uuid != UUIDHelpers::Nil)
556	    {
557	        auto out = data_part_storage_builder->writeFile(IMergeTreeDataPart::UUID_FILE_NAME, 4096, context->getWriteSettings());
558	        HashingWriteBuffer out_hashing(*out);
559	        writeUUIDText(new_data_part->uuid, out_hashing);
560	        new_data_part->checksums.files[IMergeTreeDataPart::UUID_FILE_NAME].file_size = out_hashing.count();
561	        new_data_part->checksums.files[IMergeTreeDataPart::UUID_FILE_NAME].file_hash = out_hashing.getHash();
562	    }
563	
564	    if (execute_ttl_type != ExecuteTTLType::NONE)
565	    {
566	        /// Write a file with ttl infos in json format.
567	        auto out_ttl = data_part_storage_builder->writeFile("ttl.txt", 4096, context->getWriteSettings());
568	        HashingWriteBuffer out_hashing(*out_ttl);
569	        new_data_part->ttl_infos.write(out_hashing);
570	        new_data_part->checksums.files["ttl.txt"].file_size = out_hashing.count();
571	        new_data_part->checksums.files["ttl.txt"].file_hash = out_hashing.getHash();
572	    }
573	
574	    if (!new_data_part->getSerializationInfos().empty())
575	    {
576	        auto out = data_part_storage_builder->writeFile(IMergeTreeDataPart::SERIALIZATION_FILE_NAME, 4096, context->getWriteSettings());
577	        HashingWriteBuffer out_hashing(*out);
578	        new_data_part->getSerializationInfos().writeJSON(out_hashing);
579	        new_data_part->checksums.files[IMergeTreeDataPart::SERIALIZATION_FILE_NAME].file_size = out_hashing.count();
580	        new_data_part->checksums.files[IMergeTreeDataPart::SERIALIZATION_FILE_NAME].file_hash = out_hashing.getHash();
581	    }
582	
583	    {
584	        /// Write file with checksums.
585	        auto out_checksums = data_part_storage_builder->writeFile("checksums.txt", 4096, context->getWriteSettings());
586	        new_data_part->checksums.write(*out_checksums);
587	    } /// close fd
588	
589	    {
590	        auto out = data_part_storage_builder->writeFile(IMergeTreeDataPart::DEFAULT_COMPRESSION_CODEC_FILE_NAME, 4096, context->getWriteSettings());
591	        DB::writeText(queryToString(codec->getFullCodecDesc()), *out);
592	    }
593	
594	    {
595	        /// Write a file with a description of columns.
596	        auto out_columns = data_part_storage_builder->writeFile("columns.txt", 4096, context->getWriteSettings());
597	        new_data_part->getColumns().writeText(*out_columns);
598	    } /// close fd
599	
600	    new_data_part->rows_count = source_part->rows_count;
601	    new_data_part->index_granularity = source_part->index_granularity;
602	    new_data_part->index = source_part->index;
603	    new_data_part->minmax_idx = source_part->minmax_idx;
604	    new_data_part->modification_time = time(nullptr);
605	    new_data_part->loadProjections(false, false);
606	    new_data_part->setBytesOnDisk(new_data_part->data_part_storage->calculateTotalSizeOnDisk());
607	    new_data_part->default_codec = codec;
608	    new_data_part->calculateColumnsAndSecondaryIndicesSizesOnDisk();
609	}
