685	class MergeProjectionPartsTask : public IExecutableTask
686	{
687	public:
688	
689	    MergeProjectionPartsTask(
690	        String name_,
691	        MergeTreeData::MutableDataPartsVector && parts_,
692	        const ProjectionDescription & projection_,
693	        size_t & block_num_,
694	        MutationContextPtr ctx_)
695	        : name(std::move(name_))
696	        , parts(std::move(parts_))
697	        , projection(projection_)
698	        , block_num(block_num_)
699	        , ctx(ctx_)
700	        , log(&Poco::Logger::get("MergeProjectionPartsTask"))
701	        {
702	            LOG_DEBUG(log, "Selected {} projection_parts from {} to {}", parts.size(), parts.front()->name, parts.back()->name);
703	            level_parts[current_level] = std::move(parts);
704	        }
705	
706	    void onCompleted() override { throw Exception(ErrorCodes::LOGICAL_ERROR, "Not implemented"); }
707	    StorageID getStorageID() override { throw Exception(ErrorCodes::LOGICAL_ERROR, "Not implemented"); }
708	    UInt64 getPriority() override { throw Exception(ErrorCodes::LOGICAL_ERROR, "Not implemented"); }
709	
710	    bool executeStep() override
711	    {
712	        auto & current_level_parts = level_parts[current_level];
713	        auto & next_level_parts = level_parts[next_level];
714	
715	        MergeTreeData::MutableDataPartsVector selected_parts;
716	        while (selected_parts.size() < max_parts_to_merge_in_one_level && !current_level_parts.empty())
717	        {
718	            selected_parts.push_back(std::move(current_level_parts.back()));
719	            current_level_parts.pop_back();
720	        }
721	
722	        if (selected_parts.empty())
723	        {
724	            if (next_level_parts.empty())
725	            {
726	                LOG_WARNING(log, "There is no projection parts merged");
727	
728	                /// Task is finished
729	                return false;
730	            }
731	            current_level = next_level;
732	            ++next_level;
733	        }
734	        else if (selected_parts.size() == 1)
735	        {
736	            if (next_level_parts.empty())
737	            {
738	                LOG_DEBUG(log, "Merged a projection part in level {}", current_level);
739	                auto builder = selected_parts[0]->data_part_storage->getBuilder();
740	                selected_parts[0]->renameTo(projection.name + ".proj", true, builder);
741	                selected_parts[0]->name = projection.name;
742	                selected_parts[0]->is_temp = false;
743	                builder->commit();
744	                ctx->new_data_part->addProjectionPart(name, std::move(selected_parts[0]));
745	
746	                /// Task is finished
747	                return false;
748	            }
749	            else
750	            {
751	                LOG_DEBUG(log, "Forwarded part {} in level {} to next level", selected_parts[0]->name, current_level);
752	                next_level_parts.push_back(std::move(selected_parts[0]));
753	            }
754	        }
755	        else if (selected_parts.size() > 1)
756	        {
757	            // Generate a unique part name
758	            ++block_num;
759	            auto projection_future_part = std::make_shared<FutureMergedMutatedPart>();
760	            MergeTreeData::DataPartsVector const_selected_parts(
761	                std::make_move_iterator(selected_parts.begin()), std::make_move_iterator(selected_parts.end()));
762	            projection_future_part->assign(std::move(const_selected_parts));
763	            projection_future_part->name = fmt::format("{}_{}", projection.name, ++block_num);
764	            projection_future_part->part_info = {"all", 0, 0, 0};
765	
766	            MergeTreeData::MergingParams projection_merging_params;
767	            projection_merging_params.mode = MergeTreeData::MergingParams::Ordinary;
768	            if (projection.type == ProjectionDescription::Type::Aggregate)
769	                projection_merging_params.mode = MergeTreeData::MergingParams::Aggregating;
770	
771	            const Settings & settings = ctx->context->getSettingsRef();
772	
773	            LOG_DEBUG(log, "Merged {} parts in level {} to {}", selected_parts.size(), current_level, projection_future_part->name);
774	            auto tmp_part_merge_task = ctx->mutator->mergePartsToTemporaryPart(
775	                projection_future_part,
776	                projection.metadata,
777	                ctx->mutate_entry,
778	                std::make_unique<MergeListElement>((*ctx->mutate_entry)->table_id, projection_future_part, settings),
779	                *ctx->holder,
780	                ctx->time_of_mutation,
781	                ctx->context,
782	                ctx->space_reservation,
783	                false, // TODO Do we need deduplicate for projections
784	                {},
785	                projection_merging_params,
786	                NO_TRANSACTION_PTR,
787	                ctx->new_data_part.get(),
788	                ctx->data_part_storage_builder.get(),
789	                ".tmp_proj");
790	
791	            next_level_parts.push_back(executeHere(tmp_part_merge_task));
792	            next_level_parts.back()->is_temp = true;
793	        }
794	
795	        /// Need execute again
796	        return true;
797	    }
798	private:
799	    String name;
800	    MergeTreeData::MutableDataPartsVector parts;
801	    const ProjectionDescription & projection;
802	    size_t & block_num;
803	    MutationContextPtr ctx;
804	
805	    Poco::Logger * log;
806	
807	    std::map<size_t, MergeTreeData::MutableDataPartsVector> level_parts;
808	    size_t current_level = 0;
809	    size_t next_level = 1;
810	
811	    /// TODO(nikitamikhaylov): make this constant a setting
812	    static constexpr size_t max_parts_to_merge_in_one_level = 10;
813	};
