816	// This class is responsible for:
817	// 1. get projection pipeline and a sink to write parts
818	// 2. build an executor that can write block to the input stream (actually we can write through it to generate as many parts as possible)
819	// 3. finalize the pipeline so that all parts are merged into one part
820	
821	// In short it executed a mutation for the part an original part and for its every projection
822	
823	/**
824	 *
825	 * An overview of how the process of mutation works for projections:
826	 *
827	 * The mutation for original parts is executed block by block,
828	 * but additionally we execute a SELECT query for each projection over a current block.
829	 * And we store results to a map : ProjectionName -> ArrayOfParts.
830	 *
831	 * Then, we have to merge all parts for each projection. But we will have constraint:
832	 * We cannot execute merge on more than 10 parts simulatiously.
833	 * So we build a tree of merges. At the beginning all the parts have level 0.
834	 * At each step we take not bigger than 10 parts from the same level
835	 * and merge it into a bigger part with incremented level.
836	 */
837	class PartMergerWriter
838	{
839	public:
840	
841	    explicit PartMergerWriter(MutationContextPtr ctx_)
842	        : ctx(ctx_), projections(ctx->metadata_snapshot->projections)
843	    {
844	    }
845	
846	    bool execute()
847	    {
848	        switch (state)
849	        {
850	            case State::NEED_PREPARE:
851	            {
852	                prepare();
853	
854	                state = State::NEED_MUTATE_ORIGINAL_PART;
855	                return true;
856	            }
857	            case State::NEED_MUTATE_ORIGINAL_PART:
858	            {
859	                if (mutateOriginalPartAndPrepareProjections())
860	                    return true;
861	
862	                state = State::NEED_MERGE_PROJECTION_PARTS;
863	                return true;
864	            }
865	            case State::NEED_MERGE_PROJECTION_PARTS:
866	            {
867	                if (iterateThroughAllProjections())
868	                    return true;
869	
870	                state = State::SUCCESS;
871	                return true;
872	            }
873	            case State::SUCCESS:
874	            {
875	                return false;
876	            }
877	        }
878	        return false;
879	    }
880	
881	private:
882	    void prepare();
883	    bool mutateOriginalPartAndPrepareProjections();
884	    bool iterateThroughAllProjections();
885	    void constructTaskForProjectionPartsMerge();
886	    void finalize();
887	
888	    enum class State
889	    {
890	        NEED_PREPARE,
891	        NEED_MUTATE_ORIGINAL_PART,
892	        NEED_MERGE_PROJECTION_PARTS,
893	
894	        SUCCESS
895	    };
896	
897	    State state{State::NEED_PREPARE};
898	    MutationContextPtr ctx;
899	
900	    size_t block_num = 0;
901	
902	    using ProjectionNameToItsBlocks = std::map<String, MergeTreeData::MutableDataPartsVector>;
903	    ProjectionNameToItsBlocks projection_parts;
904	    std::move_iterator<ProjectionNameToItsBlocks::iterator> projection_parts_iterator;
905	
906	    std::vector<SquashingTransform> projection_squashes;
907	    const ProjectionsDescription & projections;
908	
909	    ExecutableTaskPtr merge_projection_parts_task_ptr;
910	};
911	
912	
913	void PartMergerWriter::prepare()
914	{
915	    const auto & settings = ctx->context->getSettingsRef();
916	
917	    for (size_t i = 0, size = ctx->projections_to_build.size(); i < size; ++i)
918	    {
919	        // If the parent part is an in-memory part, squash projection output into one block and
920	        // build in-memory projection because we don't support merging into a new in-memory part.
921	        // Otherwise we split the materialization into multiple stages similar to the process of
922	        // INSERT SELECT query.
923	        if (ctx->new_data_part->getType() == MergeTreeDataPartType::InMemory)
924	            projection_squashes.emplace_back(0, 0);
925	        else
926	            projection_squashes.emplace_back(settings.min_insert_block_size_rows, settings.min_insert_block_size_bytes);
927	    }
928	}
929	
930	
931	bool PartMergerWriter::mutateOriginalPartAndPrepareProjections()
932	{
933	    Block cur_block;
934	    if (MutationHelpers::checkOperationIsNotCanceled(*ctx->merges_blocker, ctx->mutate_entry) && ctx->mutating_executor->pull(cur_block))
935	    {
936	        if (ctx->minmax_idx)
937	            ctx->minmax_idx->update(cur_block, ctx->data->getMinMaxColumnsNames(ctx->metadata_snapshot->getPartitionKey()));
938	
939	        ctx->out->write(cur_block);
940	
941	        for (size_t i = 0, size = ctx->projections_to_build.size(); i < size; ++i)
942	        {
943	            const auto & projection = *ctx->projections_to_build[i];
944	            auto projection_block = projection_squashes[i].add(projection.calculate(cur_block, ctx->context));
945	            if (projection_block)
946	            {
947	                auto tmp_part = MergeTreeDataWriter::writeTempProjectionPart(
948	                    *ctx->data, ctx->log, projection_block, projection, ctx->data_part_storage_builder, ctx->new_data_part.get(), ++block_num);
949	                tmp_part.builder->commit();
950	                tmp_part.finalize();
951	                projection_parts[projection.name].emplace_back(std::move(tmp_part.part));
952	            }
953	        }
954	
955	        (*ctx->mutate_entry)->rows_written += cur_block.rows();
956	        (*ctx->mutate_entry)->bytes_written_uncompressed += cur_block.bytes();
957	
958	        /// Need execute again
959	        return true;
960	    }
961	
962	    // Write the last block
963	    for (size_t i = 0, size = ctx->projections_to_build.size(); i < size; ++i)
964	    {
965	        const auto & projection = *ctx->projections_to_build[i];
966	        auto & projection_squash = projection_squashes[i];
967	        auto projection_block = projection_squash.add({});
968	        if (projection_block)
969	        {
970	            auto temp_part = MergeTreeDataWriter::writeTempProjectionPart(
971	                *ctx->data, ctx->log, projection_block, projection, ctx->data_part_storage_builder, ctx->new_data_part.get(), ++block_num);
972	            temp_part.builder->commit();
973	            temp_part.finalize();
974	            projection_parts[projection.name].emplace_back(std::move(temp_part.part));
975	        }
976	    }
977	
978	    projection_parts_iterator = std::make_move_iterator(projection_parts.begin());
979	
980	    /// Maybe there are no projections ?
981	    if (projection_parts_iterator != std::make_move_iterator(projection_parts.end()))
982	        constructTaskForProjectionPartsMerge();
983	
984	    /// Let's move on to the next stage
985	    return false;
986	}
987	
988	
989	void PartMergerWriter::constructTaskForProjectionPartsMerge()
990	{
991	    auto && [name, parts] = *projection_parts_iterator;
992	    const auto & projection = projections.get(name);
993	
994	    merge_projection_parts_task_ptr = std::make_unique<MergeProjectionPartsTask>
995	    (
996	        name,
997	        std::move(parts),
998	        projection,
999	        block_num,
1000	        ctx

1000	        ctx
1001	    );
1002	}
1003	
1004	
1005	bool PartMergerWriter::iterateThroughAllProjections()
1006	{
1007	    /// In case if there are no projections we didn't construct a task
1008	    if (!merge_projection_parts_task_ptr)
1009	        return false;
1010	
1011	    if (merge_projection_parts_task_ptr->executeStep())
1012	        return true;
1013	
1014	    ++projection_parts_iterator;
1015	
1016	    if (projection_parts_iterator == std::make_move_iterator(projection_parts.end()))
1017	        return false;
1018	
1019	    constructTaskForProjectionPartsMerge();
1020	
1021	    return true;
1022	}
