1024	class MutateAllPartColumnsTask : public IExecutableTask
1025	{
1026	public:
1027	
1028	    explicit MutateAllPartColumnsTask(MutationContextPtr ctx_) : ctx(ctx_) {}
1029	
1030	    void onCompleted() override { throw Exception(ErrorCodes::LOGICAL_ERROR, "Not implemented"); }
1031	    StorageID getStorageID() override { throw Exception(ErrorCodes::LOGICAL_ERROR, "Not implemented"); }
1032	    UInt64 getPriority() override { throw Exception(ErrorCodes::LOGICAL_ERROR, "Not implemented"); }
1033	
1034	    bool executeStep() override
1035	    {
1036	        switch (state)
1037	        {
1038	            case State::NEED_PREPARE:
1039	            {
1040	                prepare();
1041	
1042	                state = State::NEED_EXECUTE;
1043	                return true;
1044	            }
1045	            case State::NEED_EXECUTE:
1046	            {
1047	                if (part_merger_writer_task->execute())
1048	                    return true;
1049	
1050	                state = State::NEED_FINALIZE;
1051	                return true;
1052	            }
1053	            case State::NEED_FINALIZE:
1054	            {
1055	                finalize();
1056	
1057	                state = State::SUCCESS;
1058	                return true;
1059	            }
1060	            case State::SUCCESS:
1061	            {
1062	                return false;
1063	            }
1064	        }
1065	        return false;
1066	    }
1067	
1068	private:
1069	
1070	    void prepare()
1071	    {
1072	        ctx->data_part_storage_builder->createDirectories();
1073	
1074	        /// Note: this is done before creating input streams, because otherwise data.data_parts_mutex
1075	        /// (which is locked in data.getTotalActiveSizeInBytes())
1076	        /// (which is locked in shared mode when input streams are created) and when inserting new data
1077	        /// the order is reverse. This annoys TSan even though one lock is locked in shared mode and thus
1078	        /// deadlock is impossible.
1079	        ctx->compression_codec = ctx->data->getCompressionCodecForPart(ctx->source_part->getBytesOnDisk(), ctx->source_part->ttl_infos, ctx->time_of_mutation);
1080	
1081	        auto skip_part_indices = MutationHelpers::getIndicesForNewDataPart(ctx->metadata_snapshot->getSecondaryIndices(), ctx->for_file_renames);
1082	        ctx->projections_to_build = MutationHelpers::getProjectionsForNewDataPart(ctx->metadata_snapshot->getProjections(), ctx->for_file_renames);
1083	
1084	        if (!ctx->mutating_pipeline_builder.initialized())
1085	            throw Exception("Cannot mutate part columns with uninitialized mutations stream. It's a bug", ErrorCodes::LOGICAL_ERROR);
1086	
1087	        QueryPipelineBuilder builder(std::move(ctx->mutating_pipeline_builder));
1088	
1089	        if (ctx->metadata_snapshot->hasPrimaryKey() || ctx->metadata_snapshot->hasSecondaryIndices())
1090	        {
1091	            builder.addTransform(
1092	                std::make_shared<ExpressionTransform>(builder.getHeader(), ctx->data->getPrimaryKeyAndSkipIndicesExpression(ctx->metadata_snapshot)));
1093	
1094	            builder.addTransform(std::make_shared<MaterializingTransform>(builder.getHeader()));
1095	        }
1096	
1097	        if (ctx->execute_ttl_type == ExecuteTTLType::NORMAL)
1098	            builder.addTransform(std::make_shared<TTLTransform>(builder.getHeader(), *ctx->data, ctx->metadata_snapshot, ctx->new_data_part, ctx->time_of_mutation, true));
1099	
1100	        if (ctx->execute_ttl_type == ExecuteTTLType::RECALCULATE)
1101	            builder.addTransform(std::make_shared<TTLCalcTransform>(builder.getHeader(), *ctx->data, ctx->metadata_snapshot, ctx->new_data_part, ctx->time_of_mutation, true));
1102	
1103	        ctx->minmax_idx = std::make_shared<IMergeTreeDataPart::MinMaxIndex>();
1104	
1105	        ctx->out = std::make_shared<MergedBlockOutputStream>(
1106	            ctx->new_data_part,
1107	            ctx->data_part_storage_builder,
1108	            ctx->metadata_snapshot,
1109	            ctx->new_data_part->getColumns(),
1110	            skip_part_indices,
1111	            ctx->compression_codec,
1112	            ctx->txn);
1113	
1114	        ctx->mutating_pipeline = QueryPipelineBuilder::getPipeline(std::move(builder));
1115	        ctx->mutating_pipeline.setProgressCallback(ctx->progress_callback);
1116	        /// Is calculated inside MergeProgressCallback.
1117	        ctx->mutating_pipeline.disableProfileEventUpdate();
1118	        ctx->mutating_executor = std::make_unique<PullingPipelineExecutor>(ctx->mutating_pipeline);
1119	
1120	        part_merger_writer_task = std::make_unique<PartMergerWriter>(ctx);
1121	    }
1122	
1123	
1124	    void finalize()
1125	    {
1126	        ctx->new_data_part->minmax_idx = std::move(ctx->minmax_idx);
1127	        ctx->mutating_executor.reset();
1128	        ctx->mutating_pipeline.reset();
1129	
1130	        static_pointer_cast<MergedBlockOutputStream>(ctx->out)->finalizePart(ctx->new_data_part, ctx->need_sync);
1131	        ctx->out.reset();
1132	    }
1133	
1134	    enum class State
1135	    {
1136	        NEED_PREPARE,
1137	        NEED_EXECUTE,
1138	        NEED_FINALIZE,
1139	
1140	        SUCCESS
1141	    };
1142	
1143	    State state{State::NEED_PREPARE};
1144	
1145	    MutationContextPtr ctx;
1146	
1147	    std::unique_ptr<PartMergerWriter> part_merger_writer_task;
1148	};
