1154	
1155	    void onCompleted() override { throw Exception(ErrorCodes::LOGICAL_ERROR, "Not implemented"); }
1156	    StorageID getStorageID() override { throw Exception(ErrorCodes::LOGICAL_ERROR, "Not implemented"); }
1157	    UInt64 getPriority() override { throw Exception(ErrorCodes::LOGICAL_ERROR, "Not implemented"); }
1158	
1159	    bool executeStep() override
1160	    {
1161	        switch (state)
1162	        {
1163	            case State::NEED_PREPARE:
1164	            {
1165	                prepare();
1166	
1167	                state = State::NEED_EXECUTE;
1168	                return true;
1169	            }
1170	            case State::NEED_EXECUTE:
1171	            {
1172	                if (part_merger_writer_task && part_merger_writer_task->execute())
1173	                    return true;
1174	
1175	                state = State::NEED_FINALIZE;
1176	                return true;
1177	            }
1178	            case State::NEED_FINALIZE:
1179	            {
1180	                finalize();
1181	
1182	                state = State::SUCCESS;
1183	                return true;
1184	            }
1185	            case State::SUCCESS:
1186	            {
1187	                return false;
1188	            }
1189	        }
1190	        return false;
1191	    }
1192	
1193	private:
1194	
1195	    void prepare()
1196	    {
1197	        if (ctx->execute_ttl_type != ExecuteTTLType::NONE)
1198	            ctx->files_to_skip.insert("ttl.txt");
1199	
1200	        ctx->data_part_storage_builder->createDirectories();
1201	
1202	        /// We should write version metadata on part creation to distinguish it from parts that were created without transaction.
1203	        TransactionID tid = ctx->txn ? ctx->txn->tid : Tx::PrehistoricTID;
1204	        /// NOTE do not pass context for writing to system.transactions_info_log,
1205	        /// because part may have temporary name (with temporary block numbers). Will write it later.
1206	        ctx->new_data_part->version.setCreationTID(tid, nullptr);
1207	        ctx->new_data_part->storeVersionMetadata();
1208	
1209	        NameSet hardlinked_files;
1210	        /// Create hardlinks for unchanged files
1211	        for (auto it = ctx->source_part->data_part_storage->iterate(); it->isValid(); it->next())
1212	        {
1213	            if (ctx->files_to_skip.contains(it->name()))
1214	                continue;
1215	
1216	            String destination;
1217	            String file_name = it->name();
1218	
1219	            auto rename_it = std::find_if(ctx->files_to_rename.begin(), ctx->files_to_rename.end(), [&file_name](const auto & rename_pair)
1220	            {
1221	                return rename_pair.first == file_name;
1222	            });
1223	
1224	            if (rename_it != ctx->files_to_rename.end())
1225	            {
1226	                if (rename_it->second.empty())
1227	                    continue;
1228	                destination = rename_it->second;
1229	            }
1230	            else
1231	            {
1232	                destination = it->name();
1233	            }
1234	
1235	            if (it->isFile())
1236	            {
1237	                ctx->data_part_storage_builder->createHardLinkFrom(
1238	                    *ctx->source_part->data_part_storage, it->name(), destination);
1239	                hardlinked_files.insert(it->name());
1240	            }
1241	            else if (!endsWith(".tmp_proj", it->name())) // ignore projection tmp merge dir
1242	            {
1243	                // it's a projection part directory
1244	                ctx->data_part_storage_builder->createProjection(destination);
1245	
1246	                auto projection_data_part_storage = ctx->source_part->data_part_storage->getProjection(destination);
1247	                auto projection_data_part_storage_builder = ctx->data_part_storage_builder->getProjection(destination);
1248	
1249	                for (auto p_it = projection_data_part_storage->iterate(); p_it->isValid(); p_it->next())
1250	                {
1251	                    projection_data_part_storage_builder->createHardLinkFrom(
1252	                        *projection_data_part_storage, p_it->name(), p_it->name());
1253	                    hardlinked_files.insert(p_it->name());
1254	                }
1255	            }
1256	        }
1257	
1258	        /// Tracking of hardlinked files required for zero-copy replication.
1259	        /// We don't remove them when we delete last copy of source part because
1260	        /// new part can use them.
1261	        ctx->hardlinked_files.source_table_shared_id = ctx->source_part->storage.getTableSharedID();
1262	        ctx->hardlinked_files.source_part_name = ctx->source_part->name;
1263	        ctx->hardlinked_files.hardlinks_from_source_part = hardlinked_files;
1264	
1265	        (*ctx->mutate_entry)->columns_written = ctx->storage_columns.size() - ctx->updated_header.columns();
1266	
1267	        ctx->new_data_part->checksums = ctx->source_part->checksums;
1268	
1269	        ctx->compression_codec = ctx->source_part->default_codec;
1270	
1271	        if (ctx->mutating_pipeline_builder.initialized())
1272	        {
1273	            QueryPipelineBuilder builder(std::move(ctx->mutating_pipeline_builder));
1274	
1275	            if (ctx->execute_ttl_type == ExecuteTTLType::NORMAL)
1276	                builder.addTransform(std::make_shared<TTLTransform>(builder.getHeader(), *ctx->data, ctx->metadata_snapshot, ctx->new_data_part, ctx->time_of_mutation, true));
1277	
1278	            if (ctx->execute_ttl_type == ExecuteTTLType::RECALCULATE)
1279	                builder.addTransform(std::make_shared<TTLCalcTransform>(builder.getHeader(), *ctx->data, ctx->metadata_snapshot, ctx->new_data_part, ctx->time_of_mutation, true));
1280	
1281	            ctx->out = std::make_shared<MergedColumnOnlyOutputStream>(
1282	                ctx->data_part_storage_builder,
1283	                ctx->new_data_part,
1284	                ctx->metadata_snapshot,
1285	                ctx->updated_header,
1286	                ctx->compression_codec,
1287	                std::vector<MergeTreeIndexPtr>(ctx->indices_to_recalc.begin(), ctx->indices_to_recalc.end()),
1288	                nullptr,
1289	                ctx->source_part->index_granularity,
1290	                &ctx->source_part->index_granularity_info
1291	            );
1292	
1293	            ctx->mutating_pipeline = QueryPipelineBuilder::getPipeline(std::move(builder));
1294	            ctx->mutating_pipeline.setProgressCallback(ctx->progress_callback);
1295	            /// Is calculated inside MergeProgressCallback.
1296	            ctx->mutating_pipeline.disableProfileEventUpdate();
1297	            ctx->mutating_executor = std::make_unique<PullingPipelineExecutor>(ctx->mutating_pipeline);
1298	
1299	            ctx->projections_to_build = std::vector<ProjectionDescriptionRawPtr>{ctx->projections_to_recalc.begin(), ctx->projections_to_recalc.end()};
1300	
1301	            part_merger_writer_task = std::make_unique<PartMergerWriter>(ctx);
1302	        }
1303	    }
1304	
1305	
1306	    void finalize()
1307	    {
1308	        if (ctx->mutating_executor)
1309	        {
1310	            ctx->mutating_executor.reset();
1311	            ctx->mutating_pipeline.reset();
1312	
1313	            auto changed_checksums =
1314	                static_pointer_cast<MergedColumnOnlyOutputStream>(ctx->out)->fillChecksums(
1315	                    ctx->new_data_part, ctx->new_data_part->checksums);
1316	            ctx->new_data_part->checksums.add(std::move(changed_checksums));
1317	
1318	            static_pointer_cast<MergedColumnOnlyOutputStream>(ctx->out)->finish(ctx->need_sync);
1319	        }
1320	
1321	        for (const auto & [rename_from, rename_to] : ctx->files_to_rename)
1322	        {
1323	            if (rename_to.empty() && ctx->new_data_part->checksums.files.contains(rename_from))
1324	            {
1325	                ctx->new_data_part->checksums.files.erase(rename_from);
1326	            }
1327	            else if (ctx->new_data_part->checksums.files.contains(rename_from))
1328	            {
1329	                ctx->new_data_part->checksums.files[rename_to] = ctx->new_data_part->checksums.files[rename_from];
1330	                ctx->new_data_part->checksums.files.erase(rename_from);
1331	            }
1332	        }
1333	
1334	        MutationHelpers::finalizeMutatedPart(ctx->source_part, ctx->data_part_storage_builder, ctx->new_data_part, ctx->execute_ttl_type, ctx->compression_codec, ctx->context);
1335	    }
1336	
1337	
1338	    enum class State
1339	    {
1340	        NEED_PREPARE,
1341	        NEED_EXECUTE,
1342	        NEED_FINALIZE,
1343	
1344	        SUCCESS
1345	    };
1346	
1347	    State state{State::NEED_PREPARE};
1348	    MutationContextPtr ctx;
1349	    MergedColumnOnlyOutputStreamPtr out;
1350	
1351	    std::unique_ptr<PartMergerWriter> part_merger_writer_task{nullptr};
1352	};
