1391	bool MutateTask::execute()
1392	{
1393	
1394	    switch (state)
1395	    {
1396	        case State::NEED_PREPARE:
1397	        {
1398	            if (!prepare())
1399	                return false;
1400	
1401	            state = State::NEED_EXECUTE;
1402	            return true;
1403	        }
1404	        case State::NEED_EXECUTE:
1405	        {
1406	            if (task->executeStep())
1407	                return true;
1408	
1409	            promise.set_value(ctx->new_data_part);
1410	            return false;
1411	        }
1412	    }
1413	    return false;
1414	}
