1417	bool MutateTask::prepare()
1418	{
1419	    MutationHelpers::checkOperationIsNotCanceled(*ctx->merges_blocker, ctx->mutate_entry);
1420	
1421	    if (ctx->future_part->parts.size() != 1)
1422	        throw Exception(ErrorCodes::LOGICAL_ERROR, "Trying to mutate {} parts, not one. "
1423	            "This is a bug.", toString(ctx->future_part->parts.size()));
1424	
1425	    ctx->num_mutations = std::make_unique<CurrentMetrics::Increment>(CurrentMetrics::PartMutation);
1426	
1427	    auto context_for_reading = Context::createCopy(ctx->context);
1428	    context_for_reading->setSetting("max_streams_to_max_threads_ratio", 1);
1429	    context_for_reading->setSetting("max_threads", 1);
1430	    /// Allow mutations to work when force_index_by_date or force_primary_key is on.
1431	    context_for_reading->setSetting("force_index_by_date", false);
1432	    context_for_reading->setSetting("force_primary_key", false);
1433	
1434	    for (const auto & command : *ctx->commands)
1435	    {
1436	        if (command.partition == nullptr || ctx->source_part->info.partition_id == ctx->data->getPartitionIDFromQuery(
1437	                command.partition, context_for_reading))
1438	            ctx->commands_for_part.emplace_back(command);
1439	    }
1440	
1441	    if (ctx->source_part->isStoredOnDisk() && !isStorageTouchedByMutations(
1442	        ctx->storage_from_source_part, ctx->metadata_snapshot, ctx->commands_for_part, Context::createCopy(context_for_reading)))
1443	    {
1444	        LOG_TRACE(ctx->log, "Part {} doesn't change up to mutation version {}", ctx->source_part->name, ctx->future_part->part_info.mutation);
1445	        promise.set_value(ctx->data->cloneAndLoadDataPartOnSameDisk(ctx->source_part, "tmp_clone_", ctx->future_part->part_info, ctx->metadata_snapshot, ctx->txn, &ctx->hardlinked_files, false));
1446	        return false;
1447	    }
1448	    else
1449	    {
1450	        LOG_TRACE(ctx->log, "Mutating part {} to mutation version {}", ctx->source_part->name, ctx->future_part->part_info.mutation);
1451	    }
1452	
1453	    MutationHelpers::splitMutationCommands(ctx->source_part, ctx->commands_for_part, ctx->for_interpreter, ctx->for_file_renames);
1454	
1455	    ctx->stage_progress = std::make_unique<MergeStageProgress>(1.0);
1456	
1457	    if (!ctx->for_interpreter.empty())
1458	    {
1459	        ctx->interpreter = std::make_unique<MutationsInterpreter>(
1460	            ctx->storage_from_source_part, ctx->metadata_snapshot, ctx->for_interpreter, context_for_reading, true);
1461	        ctx->materialized_indices = ctx->interpreter->grabMaterializedIndices();
1462	        ctx->materialized_projections = ctx->interpreter->grabMaterializedProjections();
1463	        ctx->mutation_kind = ctx->interpreter->getMutationKind();
1464	        ctx->mutating_pipeline_builder = ctx->interpreter->execute();
1465	        ctx->updated_header = ctx->interpreter->getUpdatedHeader();
1466	        ctx->progress_callback = MergeProgressCallback((*ctx->mutate_entry)->ptr(), ctx->watch_prev_elapsed, *ctx->stage_progress);
1467	    }
1468	
1469	    auto single_disk_volume = std::make_shared<SingleDiskVolume>("volume_" + ctx->future_part->name, ctx->space_reservation->getDisk(), 0);
1470	    /// FIXME new_data_part is not used in the case when we clone part with cloneAndLoadDataPartOnSameDisk and return false
1471	    /// Is it possible to handle this case earlier?
1472	
1473	    auto data_part_storage = std::make_shared<DataPartStorageOnDisk>(
1474	        single_disk_volume,
1475	        ctx->data->getRelativeDataPath(),
1476	        "tmp_mut_" + ctx->future_part->name);
1477	
1478	    ctx->data_part_storage_builder = std::make_shared<DataPartStorageBuilderOnDisk>(
1479	        single_disk_volume,
1480	        ctx->data->getRelativeDataPath(),
1481	        "tmp_mut_" + ctx->future_part->name);
1482	
1483	    ctx->new_data_part = ctx->data->createPart(
1484	        ctx->future_part->name, ctx->future_part->type, ctx->future_part->part_info, data_part_storage);
1485	
1486	    ctx->new_data_part->uuid = ctx->future_part->uuid;
1487	    ctx->new_data_part->is_temp = true;
1488	    ctx->new_data_part->ttl_infos = ctx->source_part->ttl_infos;
1489	
1490	    /// It shouldn't be changed by mutation.
1491	    ctx->new_data_part->index_granularity_info = ctx->source_part->index_granularity_info;
1492	
1493	    auto [new_columns, new_infos] = MutationHelpers::getColumnsForNewDataPart(
1494	        ctx->source_part, ctx->updated_header, ctx->storage_columns,
1495	        ctx->source_part->getSerializationInfos(), ctx->commands_for_part);
1496	
1497	    ctx->new_data_part->setColumns(new_columns);
1498	    ctx->new_data_part->setSerializationInfos(new_infos);
1499	    ctx->new_data_part->partition.assign(ctx->source_part->partition);
1500	
1501	    /// Don't change granularity type while mutating subset of columns
1502	    ctx->mrk_extension = ctx->source_part->index_granularity_info.is_adaptive ? getAdaptiveMrkExtension(ctx->new_data_part->getType())
1503	                                                                         : getNonAdaptiveMrkExtension();
1504	
1505	    const auto data_settings = ctx->data->getSettings();
1506	    ctx->need_sync = needSyncPart(ctx->source_part->rows_count, ctx->source_part->getBytesOnDisk(), *data_settings);
1507	    ctx->execute_ttl_type = ExecuteTTLType::NONE;
1508	
1509	    if (ctx->mutating_pipeline_builder.initialized())
1510	        ctx->execute_ttl_type = MutationHelpers::shouldExecuteTTL(ctx->metadata_snapshot, ctx->interpreter->getColumnDependencies());
1511	
1512	    /// All columns from part are changed and may be some more that were missing before in part
1513	    /// TODO We can materialize compact part without copying data
1514	    if (!isWidePart(ctx->source_part)
1515	        || (ctx->mutation_kind == MutationsInterpreter::MutationKind::MUTATE_OTHER && ctx->interpreter && ctx->interpreter->isAffectingAllColumns()))
1516	    {
1517	        task = std::make_unique<MutateAllPartColumnsTask>(ctx);
1518	    }
1519	    else /// TODO: check that we modify only non-key columns in this case.
1520	    {
1521	        /// We will modify only some of the columns. Other columns and key values can be copied as-is.
1522	        for (const auto & name_type : ctx->updated_header.getNamesAndTypesList())
1523	            ctx->updated_columns.emplace(name_type.name);
1524	
1525	        ctx->indices_to_recalc = MutationHelpers::getIndicesToRecalculate(
1526	            ctx->mutating_pipeline_builder, ctx->updated_columns, ctx->metadata_snapshot, ctx->context, ctx->materialized_indices, ctx->source_part);
1527	        ctx->projections_to_recalc = MutationHelpers::getProjectionsToRecalculate(
1528	            ctx->updated_columns, ctx->metadata_snapshot, ctx->materialized_projections, ctx->source_part);
1529	
1530	        ctx->files_to_skip = MutationHelpers::collectFilesToSkip(
1531	            ctx->source_part,
1532	            ctx->updated_header,
1533	            ctx->indices_to_recalc,
1534	            ctx->mrk_extension,
1535	            ctx->projections_to_recalc);
1536	        ctx->files_to_rename = MutationHelpers::collectFilesForRenames(ctx->source_part, ctx->for_file_renames, ctx->mrk_extension);
1537	
1538	        if (ctx->indices_to_recalc.empty() &&
1539	            ctx->projections_to_recalc.empty() &&
1540	            ctx->mutation_kind != MutationsInterpreter::MutationKind::MUTATE_OTHER
1541	            && ctx->files_to_rename.empty())
1542	        {
1543	            LOG_TRACE(ctx->log, "Part {} doesn't change up to mutation version {} (optimized)", ctx->source_part->name, ctx->future_part->part_info.mutation);
1544	            promise.set_value(ctx->data->cloneAndLoadDataPartOnSameDisk(ctx->source_part, "tmp_mut_", ctx->future_part->part_info, ctx->metadata_snapshot, ctx->txn, &ctx->hardlinked_files, false));
1545	            return false;
1546	        }
1547	
1548	        task = std::make_unique<MutateSomePartColumnsTask>(ctx);
1549	    }
1550	
1551	    return true;
1552	}
